/**
 * Robust Standalone Canvas Charting Engine (Chart.js compatible API)
 * Zero external dependencies. Fully offline-capable for institutional portals.
 */
(function(global) {
    function Chart(ctx, config) {
        if (!ctx) return;
        var canvas = ctx.canvas || ctx;
        var context = canvas.getContext ? canvas.getContext('2d') : ctx;
        this.canvas = canvas;
        this.ctx = context;
        this.config = config || {};
        this.init();
    }

    Chart.prototype.init = function() {
        var self = this;
        this.render();
        window.addEventListener('resize', function() {
            self.render();
        });
    };

    Chart.prototype.destroy = function() {
        if (this.ctx && this.canvas) {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        }
    };

    Chart.prototype.update = function() {
        this.render();
    };

    Chart.prototype.render = function() {
        var canvas = this.canvas;
        var ctx = this.ctx;
        if (!canvas || !ctx) return;

        // Auto-scale canvas for devicePixelRatio
        var rect = canvas.getBoundingClientRect();
        var dpr = window.devicePixelRatio || 1;
        var width = rect.width || canvas.width || 400;
        var height = rect.height || canvas.height || 220;

        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);

        ctx.clearRect(0, 0, width, height);

        var data = this.config.data || {};
        var labels = data.labels || [];
        var datasets = data.datasets || [];
        var options = this.config.options || {};
        var type = this.config.type || 'bar';

        if (!labels.length || !datasets.length) return;

        var padding = { top: 30, right: 25, bottom: 45, left: 50 };
        var chartW = width - padding.left - padding.right;
        var chartH = height - padding.top - padding.bottom;

        // Calculate Min and Max
        var allValues = [];
        datasets.forEach(function(ds) {
            (ds.data || []).forEach(function(v) { allValues.push(v); });
        });
        var maxVal = Math.max.apply(null, allValues.concat([0]));
        if (options.scales && options.scales.y && options.scales.y.max) {
            maxVal = Math.max(maxVal, options.scales.y.max);
        }
        var minVal = 0;
        if (maxVal === 0) maxVal = 100;
        maxVal = Math.ceil(maxVal * 1.15);

        // Draw Y Axis grid & labels
        var steps = 4;
        ctx.lineWidth = 1;
        ctx.strokeStyle = '#e2e8f0';
        ctx.fillStyle = '#64748b';
        ctx.font = '11px sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        for (var s = 0; s <= steps; s++) {
            var val = (maxVal / steps) * s;
            var y = padding.top + chartH - (chartH * (val / maxVal));

            ctx.beginPath();
            ctx.moveTo(padding.left, y);
            ctx.lineTo(width - padding.right, y);
            ctx.stroke();

            var unit = '';
            if (options.scales && options.scales.y && options.scales.y.ticks && options.scales.y.ticks.callback) {
                unit = options.scales.y.ticks.callback(val);
            } else {
                unit = Math.round(val);
            }
            ctx.fillText(unit, padding.left - 8, y);
        }

        // Draw X Axis labels
        var xStep = chartW / labels.length;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        labels.forEach(function(label, idx) {
            var x = padding.left + (idx + 0.5) * xStep;
            ctx.fillText(label, x, height - padding.bottom + 10);
        });

        // Draw Data
        if (type === 'bar') {
            var numDs = datasets.length;
            var groupW = xStep * 0.7;
            var barW = groupW / numDs;

            datasets.forEach(function(ds, dsIdx) {
                var color = ds.backgroundColor || '#1a365d';
                var border = ds.borderColor || color;
                ctx.fillStyle = Array.isArray(color) ? color[0] : color;

                (ds.data || []).forEach(function(val, idx) {
                    var x = padding.left + (idx * xStep) + (xStep - groupW) / 2 + (dsIdx * barW);
                    var bH = (val / maxVal) * chartH;
                    var y = padding.top + chartH - bH;

                    if (Array.isArray(color)) {
                        ctx.fillStyle = color[idx % color.length];
                    }

                    // Rounded top corners on bars
                    var r = Math.min(4, barW / 2);
                    ctx.beginPath();
                    ctx.moveTo(x + r, y);
                    ctx.lineTo(x + barW - r, y);
                    ctx.quadraticCurveTo(x + barW, y, x + barW, y + r);
                    ctx.lineTo(x + barW, padding.top + chartH);
                    ctx.lineTo(x, padding.top + chartH);
                    ctx.lineTo(x, y + r);
                    ctx.quadraticCurveTo(x, y, x + r, y);
                    ctx.closePath();
                    ctx.fill();

                    // Value label on top of bar
                    ctx.fillStyle = '#334155';
                    ctx.font = 'bold 10px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(val, x + barW / 2, y - 12);
                    ctx.fillStyle = Array.isArray(color) ? color[0] : color;
                });
            });
        } else if (type === 'line') {
            datasets.forEach(function(ds) {
                var color = ds.borderColor || '#1a365d';
                var fill = ds.backgroundColor || 'rgba(26, 54, 93, 0.1)';

                var points = [];
                (ds.data || []).forEach(function(val, idx) {
                    var x = padding.left + (idx + 0.5) * xStep;
                    var y = padding.top + chartH - ((val / maxVal) * chartH);
                    points.push({ x: x, y: y, val: val });
                });

                if (ds.fill && points.length) {
                    ctx.beginPath();
                    ctx.moveTo(points[0].x, padding.top + chartH);
                    points.forEach(function(p) { ctx.lineTo(p.x, p.y); });
                    ctx.lineTo(points[points.length - 1].x, padding.top + chartH);
                    ctx.closePath();
                    ctx.fillStyle = fill;
                    ctx.fill();
                }

                ctx.beginPath();
                ctx.lineWidth = ds.borderWidth || 3;
                ctx.strokeStyle = color;
                points.forEach(function(p, pIdx) {
                    if (pIdx === 0) ctx.moveTo(p.x, p.y);
                    else ctx.lineTo(p.x, p.y);
                });
                ctx.stroke();

                // Draw points and values
                points.forEach(function(p) {
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
                    ctx.fillStyle = color;
                    ctx.fill();
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = 2;
                    ctx.stroke();

                    ctx.fillStyle = '#0f2b48';
                    ctx.font = 'bold 10px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(p.val + '%', p.x, p.y - 12);
                });
            });
        }

        // Draw Legend if multiple datasets
        if (datasets.length > 1) {
            var legendX = width / 2;
            var legendY = 12;
            var totalLegW = datasets.reduce(function(acc, d) { return acc + (d.label ? d.label.length * 7 + 30 : 0); }, 0);
            var currX = legendX - (totalLegW / 2);

            datasets.forEach(function(ds) {
                var c = Array.isArray(ds.backgroundColor) ? ds.backgroundColor[0] : (ds.borderColor || ds.backgroundColor);
                ctx.fillStyle = c;
                ctx.fillRect(currX, legendY, 12, 10);
                ctx.fillStyle = '#475569';
                ctx.font = '10px sans-serif';
                ctx.textAlign = 'left';
                ctx.textBaseline = 'middle';
                ctx.fillText(ds.label || '', currX + 16, legendY + 5);
                currX += (ds.label ? ds.label.length * 7 + 30 : 50);
            });
        }
    };

    global.Chart = global.Chart || Chart;
})(window);
